/* Simple semaphore bulkhead (Java) */
import java.util.concurrent.Semaphore;

public class SimpleBulkhead {
  private final Semaphore sem = new Semaphore(5); // allow 5 concurrent

  public String handleRequest() {
    if (!sem.tryAcquire()) {
      return "Service busy - try later"; // fast fail / fallback
    }
    try {
      // expensive work
      return doWork();
    } finally {
      sem.release();
    }
  }

  private String doWork() { return "OK"; }
}
